function rupiah(int $value): string { return 'Rp ' . number_format($value, 0, ',', '.'); }
function h(string $value): string { return htmlspecialchars($value, ENT_QUOTES, 'UTF-8'); }
function current_user(): ?array { return $_SESSION['user'] ?? null; }
$action = $_POST['action'] ?? $_GET['action'] ?? null;
if ($action === 'login' && $_SERVER['REQUEST_METHOD'] === 'POST') {
 $email = strtolower(trim((string) ($_POST['email'] ?? ''))); $password = (string) ($_POST['password'] ?? '');
 if (isset($users[$email]) && password_verify($password, $users[$email]['password'])) { $_SESSION['user'] = ['email'=>$email,'name'=>$users[$email]['name'],'role'=>$users[$email]['role']]; $_SESSION['audit'][] = date('Y-m-d H:i:s') . " LOGIN $email"; header('Location: ?page=dashboard'); exit; }
 $_SESSION['flash'] = 'Login gagal. Pakai akun demo dan password demo12345.';
}
if ($action === 'logout') { $_SESSION = []; session_destroy(); header('Location: ./'); exit; }
if ($action === 'impersonate' && current_user() && in_array(current_user()['role'], ['SUPER_ADMIN','ADMIN'], true)) { $_SESSION['impersonating'] = ['name'=>'PT ABC Indonesia','role'=>'CLIENT']; $_SESSION['audit'][] = date('Y-m-d H:i:s') . ' IMPERSONATE client@gatra.local'; header('Location: ?page=dashboard'); exit; }
if ($action === 'exit-impersonation') { unset($_SESSION['impersonating']); header('Location: ?page=dashboard'); exit; }
$page = $_GET['page'] ?? 'home'; $user = current_user(); $effectiveRole = $_SESSION['impersonating']['role'] ?? ($user['role'] ?? null); $effectiveName = $_SESSION['impersonating']['name'] ?? ($user['name'] ?? null); $flash = $_SESSION['flash'] ?? null; unset($_SESSION['flash']);
?>
